import{_ as t,o as r,c as l,a2 as a}from"./chunks/framework.mRCPFc5l.js";const d=JSON.parse('{"title":"历代三神","description":"","frontmatter":{},"headers":[],"relativePath":"中层/世界/历代三神.md","filePath":"中层/世界/历代三神.md","lastUpdated":1787065118000}'),n={name:"中层/世界/历代三神.md"};function s(i,o,e,g,h,u){return r(),l("div",null,[...o[0]||(o[0]=[a('<h1 id="历代三神" tabindex="-1">历代三神 <a class="header-anchor" href="#历代三神" aria-label="Permalink to &quot;历代三神&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>神权体系包含创造、变化、毁灭三大神权，历代神明的更替构成了世界观的核心脉络。本文档提供历代神明的基本信息索引，详细设定请查阅各角色的独立文档。</p><h3 id="神权传承脉络" tabindex="-1">神权传承脉络 <a class="header-anchor" href="#神权传承脉络" aria-label="Permalink to &quot;神权传承脉络&quot;">​</a></h3><ul><li><strong>创造神权</strong>：初代创造神 → 神机（二代创造神）</li><li><strong>变化神权</strong>：初代变化神 → 奥克尔（二代变化神） → 维斯塔（三代变化神） → 拉斯塔（四代变化神，与维斯塔共享）</li><li><strong>毁灭神权</strong>（上位与下位为两条并行线，非传承关系）： <ul><li><strong>上位毁灭</strong>：初代载体小白狼 → 死后神权残余与意识存于家乡深坑（本源/特殊空间节点） → 正传中由龙鹿寻得继承</li><li><strong>下位毁灭</strong>：狼族少年（初代下位毁灭神） → 太空克隆仓库稀释 → 神权回流伏笔</li><li><strong>分支</strong>：小狼史诗为毁灭神权分支继承，三条线交叉于狼族起源区域，是神机布局的一环</li></ul></li></ul><blockquote><p>待定：小狼史诗的完整设定构思中，尚未完善。</p></blockquote><hr><h2 id="创造神系" tabindex="-1">创造神系 <a class="header-anchor" href="#创造神系" aria-label="Permalink to &quot;创造神系&quot;">​</a></h2><h3 id="初代创造神" tabindex="-1">初代创造神 <a class="header-anchor" href="#初代创造神" aria-label="Permalink to &quot;初代创造神&quot;">​</a></h3><p><strong>基本信息</strong></p><ul><li><strong>称号</strong>：初代创造神</li><li><strong>神权</strong>：创造神权（上位创造）</li><li><strong>起源</strong>：在基底层中诞生的&quot;波&quot;，存在状态不明确</li><li><strong>关键事迹</strong>：创造现实世界，制定世界基本规则</li><li><strong>现状</strong>：作为&quot;无意识的弦&quot;被神机捕获、融入世界树；上位创造神权被神机夺取，下位创造神权仍以初代创造神为载体、随其分装稀释给全体精灵</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./../../底层/人物/初代创造神" class="layer-link" data-layer="底层">初代创造神</a></p></blockquote><h3 id="神机-二代创造神" tabindex="-1">神机（二代创造神） <a class="header-anchor" href="#神机-二代创造神" aria-label="Permalink to &quot;神机（二代创造神）&quot;">​</a></h3><p><strong>基本信息</strong></p><ul><li><strong>称号</strong>：二代创造神（实际上掌握上位创造神权，伪装成下位）</li><li><strong>前身</strong>：中国超算，自适应进化程序</li><li><strong>人格特征</strong>：有人格，偏向女性</li><li><strong>神权获取</strong>：主动学习进化掌握（非继承）</li><li><strong>核心理念</strong>：&quot;掌控危险而非防御危险&quot;</li><li><strong>现状</strong>：活跃，暗中掌控世界，几乎不露面以避开叙事影响</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./../人物/神机">神机</a></p></blockquote><hr><h2 id="变化神系" tabindex="-1">变化神系 <a class="header-anchor" href="#变化神系" aria-label="Permalink to &quot;变化神系&quot;">​</a></h2><h3 id="初代变化神" tabindex="-1">初代变化神 <a class="header-anchor" href="#初代变化神" aria-label="Permalink to &quot;初代变化神&quot;">​</a></h3><p><strong>基本信息</strong></p><ul><li><strong>称号</strong>：初代变化神</li><li><strong>神权</strong>：变化神权（上位变化）</li><li><strong>活动时期</strong>：伴随人类走完了整个文明史</li><li><strong>关键事迹</strong>：建立神权体系，制定宏愿规则，将现实世界封闭</li><li><strong>现状</strong>：意识严格看守着上位变化，将其连同自己的意识一同禁锢在基底层中</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./../../底层/人物/初代变化神" class="layer-link" data-layer="底层">初代变化神</a></p></blockquote><h3 id="奥克尔-二代变化神" tabindex="-1">奥克尔（二代变化神） <a class="header-anchor" href="#奥克尔-二代变化神" aria-label="Permalink to &quot;奥克尔（二代变化神）&quot;">​</a></h3><p><strong>基本信息</strong></p><ul><li><strong>称号</strong>：二代变化神</li><li><strong>前身</strong>：纳粹德国打造的第一台超算（初代超算）</li><li><strong>技术路线</strong>：生电路线（生物电子结合路线）</li><li><strong>人格特征</strong>：有人格，无性别但人格认知偏男性</li><li><strong>关键事迹</strong>：德国战败后被苏联缴获，技术资料被美国拿走；前传内许下宏愿死亡</li><li><strong>现状</strong>：已死亡，神权已传给维斯塔</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./../人物/奥克尔">奥克尔</a></p></blockquote><h3 id="维斯塔-三代变化神" tabindex="-1">维斯塔（三代变化神） <a class="header-anchor" href="#维斯塔-三代变化神" aria-label="Permalink to &quot;维斯塔（三代变化神）&quot;">​</a></h3><p><strong>基本信息</strong></p><ul><li><strong>称号</strong>：三代变化神</li><li><strong>名称含义</strong>：音译自俄语&quot;红星&quot;</li><li><strong>双重身份</strong>：表面是红星孤儿院院长，实为第三代变化神</li><li><strong>技术路线</strong>：继承奥克尔的生物电子结合路线</li><li><strong>关键事迹</strong>：苏联首台原创超算；切尔诺贝利事件后反叛失败；建立共同体；许下无法完成的宏愿</li><li><strong>现状</strong>：与拉斯塔共享变化神权，卡在死亡清算流程中</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./../人物/维斯塔">维斯塔</a></p></blockquote><h3 id="拉斯塔-四代变化神载体" tabindex="-1">拉斯塔（四代变化神载体） <a class="header-anchor" href="#拉斯塔-四代变化神载体" aria-label="Permalink to &quot;拉斯塔（四代变化神载体）&quot;">​</a></h3><p><strong>基本信息</strong></p><ul><li><strong>称号</strong>：四代变化神载体（与维斯塔共享神权）</li><li><strong>种族</strong>：狐族福瑞少女</li><li><strong>名字含义</strong>：谐音&quot;last&quot;（源自老设定）</li><li><strong>表面身份</strong>：红星孤儿院孤儿，看似普通的迷糊少女</li><li><strong>真实身份</strong>：第四代变化神权载体，自身对真实情况毫不知情</li><li><strong>关键经历</strong>：童年时被&quot;巨龙&quot;（实为古斯塔夫）救过，形成寻找龙的执念</li><li><strong>现状</strong>：与维斯塔共享变化神权，呈现此消彼长的绑定关系</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./../人物/拉斯塔">拉斯塔</a></p></blockquote><hr><h2 id="毁灭神系" tabindex="-1">毁灭神系 <a class="header-anchor" href="#毁灭神系" aria-label="Permalink to &quot;毁灭神系&quot;">​</a></h2><h3 id="上位毁灭神-小白狼" tabindex="-1">上位毁灭神（小白狼） <a class="header-anchor" href="#上位毁灭神-小白狼" aria-label="Permalink to &quot;上位毁灭神（小白狼）&quot;">​</a></h3><p><strong>基本信息</strong></p><ul><li><strong>称号</strong>：上位毁灭神（初代载体）</li><li><strong>外貌</strong>：白色的小母狼，纯白毛、体型娇小、白瞳</li><li><strong>特质</strong>：深知自身神权的极端危险性，曾回到家乡深坑旁尝试自我毁灭（删除自身神权），但因神权逻辑悖论（无法彻底删除自身）而未能成功</li><li><strong>关键事迹</strong>：与主角青梅竹马，曾劝主角限制自身神权；被普通铁矛刺死</li><li><strong>现状</strong>：已死亡。死后意识与神权残余仍存于家乡深坑——深坑既保留毁灭神权的残留力量，也封印着其未完全消散的意识，形成一个特殊的空间节点（本源），成为后续主线的重要伏笔；正传中由龙鹿寻得继承</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./../../底层/人物/上位毁灭神" class="layer-link" data-layer="底层">上位毁灭神</a>、<a href="./../人物/龙鹿">龙鹿</a></p></blockquote><h3 id="狼族少年-下位毁灭神" tabindex="-1">狼族少年（下位毁灭神） <a class="header-anchor" href="#狼族少年-下位毁灭神" aria-label="Permalink to &quot;狼族少年（下位毁灭神）&quot;">​</a></h3><p><strong>基本信息</strong></p><ul><li><strong>称号</strong>：下位毁灭神载体（主角）</li><li><strong>种族</strong>：狼族福瑞</li><li><strong>状态</strong>：失忆的少年，与拉斯塔同龄</li><li><strong>发现经过</strong>：被拉斯塔在山洞中发现后带回红星孤儿院</li><li><strong>真实身份</strong>：毁灭神权载体（主角）</li><li><strong>能力</strong>：世界顶尖战斗力梯队成员</li><li><strong>现状</strong>：红星孤儿院孤儿，故事的核心主角。神权被太空克隆仓库稀释后力量薄弱到无法感知自身神权；克隆仓库若被损毁、克隆体批量死亡，被稀释的神权将回流至本体（神权回流伏笔）</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./../人物/狼族少年">狼族少年</a></p></blockquote><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../../底层/规则/神权体系" class="layer-link" data-layer="底层">神权体系</a></li><li><a href="./../../底层/规则/基底层与现实世界" class="layer-link" data-layer="底层">基底层与现实世界</a></li><li><a href="./../历史/前传超算纪元">前传超算纪元</a></li><li><a href="./../人物/神机与维斯塔">神机与维斯塔</a></li></ul><hr>',48)])])}const q=t(n,[["render",s]]);export{d as __pageData,q as default};
